    /*
     * Add to the AircraftFamilies
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	AircraftProgram
     */
    public AircraftProgram addToAircraftFamilies( UUID parentId, AircraftFamily addTo ) {
	    LOGGER.info("handling AssignAircraftFamiliesToAircraftProgramEvent - " );
	    
	    AircraftProgram parentEntity = repository.findById(parentId).get();
	    AircraftFamily child = registry.project( AircraftFamily.class, addTo.getAircraftFamilyId());
	    
	    parentEntity.getAircraftFamilies().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the AircraftFamilies
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	AircraftProgram
     */
	public AircraftProgram removeFromAircraftFamilies( UUID parentId, AircraftFamily removeFrom ) {
	    LOGGER.info("handling RemoveAircraftFamiliesFromAircraftProgramEvent " );
	
	    AircraftProgram parentEntity = repository.findById(parentId).get();
	    AircraftFamily child = registry.project( AircraftFamily.class, removeFrom.getAircraftFamilyId());
	    
	    parentEntity.getAircraftFamilies().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

